+// Profit shown on each order row.
+export function OrderProfit({ order }: { order: { pricePaise: bigint; cogsPaise: bigint; feePaise: bigint } }) {
+  const profit = order.pricePaise - order.cogsPaise - order.feePaise
+  return <span>{(Number(profit) / 100).toFixed(2)}</span>
+}
